#include <iostream>
#include <string>
using namespace std;

int main() {
    string s = "Hi";
    cout << "size: " << s.size() << endl;
    cout << "capacity: " << s.capacity() << endl;

    s += " World!";
    cout << "size: " << s.size() << endl;
    cout << "capacity: " << s.capacity() << endl;
    return 0;
}
